function build(seed: ArticleSeed): Post {
  const world = worlds.find((w) => w.slug === seed.cluster)!;
  const pillarSlugs: Record<string, string> = {
    space:'sourojogoter-groho', physics:'sorol-jontro-kake-bole', chemistry:'podarther-obostha',
    life:'salokshongshleshon-kake-bole', nature:'chhoy-ritu-baro-mash', food:'khaddyer-upadan',
    math:'bhognangsho-doshomik-shotokra', money:'shishuke-takar-hisab-shekhano',
    language:'bangla-bornomala-shekhano', social:'shishur-rag-samlano', discovery:'ghore-boshe-biggan-porikkha',
  };
  return {
    slug: seed.slug, title: seed.title, description: seed.description,
    cluster: seed.cluster, updated: '2026-10-04', generatedCover: true,
    intro: [seed.intro], featuredAnswer: seed.answer,
    sections: [
      { h: 'কেন বিষয়টি জানা দরকার', p: [seed.why] },
      { h: 'একটি পরিচিত উদাহরণ', p: [seed.example] },
      { h: 'নিজে দেখে শেখো', p: [seed.tryIt] },
    ],
    faq: [{ q: seed.faq, a: seed.faqAnswer }],
    refs: [
      { label: `${world.bn} ভুবন`, href: `/${world.slug}/`, note: 'এই বিষয়ের থ্রিডি দৃশ্য, সম্পর্কিত পাঠ ও হাতে-কলমে কাজ দেখো।' },
      { label: 'মূল পরিচিতি: এই ভুবনের বিষয়গুলো', href: `/blog/${pillarSlugs[seed.cluster]}/`, note: 'এই ভুবনের মূল ধারণা ও পটভূমি পড়ো।' },
    ],
  };
}

const posts: Post[] = seeds.map(build);
const counts = new Map<string, number>();
for (const post of posts) counts.set(post.cluster, (counts.get(post.cluster) ?? 0) + 1);
export const QUESTION_POSTS_PER_WORLD = counts;
export default posts;
